insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-motiva-a-las-personas-a-participar-en-actividades-comunitari','sociedad',array['educacion']::text[],'¿Qué motiva a las personas a participar en actividades comunitarias, y por qué algunas no quieren hacerlo?','Descubre qué lleva a algunas personas a sumarse a una actividad comunitaria y qué hace que otras se mantengan al margen, con una encuesta breve y entrevistas voluntarias y anónimas.','Investigación','3 a 4 semanas',24,array['Motivación','Participación comunitaria']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de encuestas. analisis cualitativo. graficos. redaccion de conclusiones. un formulario en linea. hoja de calculo. una guia de conversacion.',$a1sld${"id": "que-motiva-a-las-personas-a-participar-en-actividades-comunitari", "area": "sociedad", "areas2": ["educacion"], "titulo": "¿Qué motiva a las personas a participar en actividades comunitarias, y por qué algunas no quieren hacerlo?", "resumen": "Descubre qué lleva a algunas personas a sumarse a una actividad comunitaria y qué hace que otras se mantengan al margen, con una encuesta breve y entrevistas voluntarias y anónimas.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Motivación", "Participación comunitaria"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Toda actividad comunitaria depende de que alguien se anime a participar, pero no sabemos bien por qué unos lo hacen y otros no. Puede ser por interés, por amistad, por tiempo disponible, por desconfianza o simplemente porque nadie los invitó.", "Entender las razones permite convocar mejor y no culpar a quien no participa."], "desarrollar": ["Diseña una encuesta de ocho a diez preguntas para personas de una comunidad, un colegio o una universidad sobre si participan o no en actividades comunitarias y por qué. Complementa con tres a cinco conversaciones breves y voluntarias.", "Agrupa las razones en motivaciones, como interés, sentido de pertenencia o invitación directa, y en frenos, como tiempo, desconfianza o desconocimiento. Resume los hallazgos en un gráfico y propón cinco formas de convocar mejor."], "ampliaciones": [{"titulo": "Primera invitación", "aporta": "analiza cómo influye que alguien te invite personalmente."}, {"titulo": "Por edades", "aporta": "compara motivaciones entre jóvenes y adultos."}, {"titulo": "Tipo de actividad", "aporta": "compara qué actividades atraen más y por qué."}], "objetivos": ["Diseñar una encuesta anónima.", "Agrupar motivaciones y frenos.", "Interpretar los hallazgos con cuidado.", "Proponer formas de convocar."], "habilidades": ["Diseño de encuestas.", "Análisis cualitativo.", "Gráficos.", "Redacción de conclusiones."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Una guía de conversación."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo estudio sirve para entender la participación en sindicatos, clubes o equipos de trabajo."}$a1sld$::jsonb,11),
('disenando-una-iniciativa-de-voluntariado-o-de-impacto-social-par','sociedad',array['educacion']::text[],'Diseñando una iniciativa de voluntariado o de impacto social para una necesidad concreta','Parte de una necesidad real de tu entorno, como útiles escolares o acompañamiento a personas mayores, y diseña una iniciativa de voluntariado con objetivo, actividades, recursos y forma de saber si funcionó.','Plan','4 a 6 semanas',28,array['Voluntariado','Impacto social']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de proyectos. escucha activa. planificacion. redaccion. un editor de documentos. hoja de calculo. una guia de conversacion.',$a2sld${"id": "disenando-una-iniciativa-de-voluntariado-o-de-impacto-social-par", "area": "sociedad", "areas2": ["educacion"], "titulo": "Diseñando una iniciativa de voluntariado o de impacto social para una necesidad concreta", "resumen": "Parte de una necesidad real de tu entorno, como útiles escolares o acompañamiento a personas mayores, y diseña una iniciativa de voluntariado con objetivo, actividades, recursos y forma de saber si funcionó.", "tipo": "Plan", "tiempo": "4 a 6 semanas", "horas": 28, "etiquetas": ["Voluntariado", "Impacto social"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Muchas buenas intenciones se quedan en ideas sueltas porque no se diseñan: no se define a quién se ayuda, quién hace qué ni cómo se sabrá si sirvió. Eso lleva a esfuerzos desordenados y a voluntarios que se cansan.", "Diseñar la iniciativa antes de lanzarla aumenta sus posibilidades de ayudar de verdad."], "desarrollar": ["Elige una necesidad y conversa con las personas que la viven, con respeto, para entenderla. Define el objetivo, el grupo al que se dirige, las actividades, los recursos necesarios, los roles, un calendario y dos o tres indicadores de resultado.", "Presenta el diseño en un documento de dos páginas, anticipa los riesgos, como poca asistencia o falta de materiales, y define cómo se medirá el impacto. Consúltalo con una persona de la comunidad y ajústalo."], "ampliaciones": [{"titulo": "Presupuesto", "aporta": "estima el costo real de la iniciativa y cómo cubrirlo."}, {"titulo": "Voluntarios", "aporta": "define cómo reclutar, orientar y despedir a voluntarios."}, {"titulo": "Evaluación", "aporta": "diseña una encuesta corta de satisfacción de participantes."}], "objetivos": ["Entender una necesidad concreta.", "Diseñar objetivos y actividades.", "Definir indicadores.", "Validar con la comunidad."], "habilidades": ["Diseño de proyectos.", "Escucha activa.", "Planificación.", "Redacción."], "herramientas": ["Un editor de documentos.", "Hoja de cálculo.", "Una guía de conversación."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Presenta la propuesta como diseño y no la ejecutes sin permiso de la comunidad o de la institución involucrada."], "otroSector": "El mismo diseño sirve para campañas de responsabilidad social en una empresa."}$a2sld$::jsonb,12),
('analizando-el-impacto-del-voluntariado-en-una-comunidad','sociedad',array['educacion']::text[],'Analizando el impacto del voluntariado en una comunidad','Revisa qué se sabe sobre el efecto del voluntariado en las comunidades y en quienes lo hacen, y diseña una forma sencilla de medir ese impacto en una iniciativa concreta.','Análisis','3 a 4 semanas',24,array['Impacto','Voluntariado']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion analisis de informes. diseno de indicadores. pensamiento critico. redaccion. informes publicos. hoja de calculo. un editor de documentos.',$a3sld${"id": "analizando-el-impacto-del-voluntariado-en-una-comunidad", "area": "sociedad", "areas2": ["educacion"], "titulo": "Analizando el impacto del voluntariado en una comunidad", "resumen": "Revisa qué se sabe sobre el efecto del voluntariado en las comunidades y en quienes lo hacen, y diseña una forma sencilla de medir ese impacto en una iniciativa concreta.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Impacto", "Voluntariado"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Se dice que el voluntariado hace bien, pero rara vez se mide a quién, cuánto y de qué manera. Algunas iniciativas ayudan mucho y otras generan dependencia, expectativas que no se cumplen o cansancio en los voluntarios.", "Medir el impacto permite mejorar y rendir cuentas con honestidad."], "desarrollar": ["Con informes públicos de organizaciones y estudios abiertos, reúne tres ejemplos de voluntariado y describe qué resultados dicen haber logrado y cómo los midieron. Distingue los datos de las opiniones.", "Diseña una ficha de medición con cinco indicadores simples, como personas atendidas, continuidad, satisfacción, aprendizajes de voluntarios y cambios observados, y aplícala con datos ficticios a una iniciativa de ejemplo."], "ampliaciones": [{"titulo": "Impacto en quien da", "aporta": "analiza qué aprenden los voluntarios."}, {"titulo": "Efectos no deseados", "aporta": "identifica riesgos como dependencia o duplicidad."}, {"titulo": "Informe corto", "aporta": "redacta un informe de impacto de una página."}], "objetivos": ["Revisar evidencia del voluntariado.", "Distinguir datos y opiniones.", "Diseñar indicadores.", "Redactar un informe."], "habilidades": ["Análisis de informes.", "Diseño de indicadores.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Informes públicos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Cita siempre las fuentes y no atribuyas resultados a organizaciones sin respaldo."], "otroSector": "La misma ficha sirve para medir el efecto de programas de responsabilidad social o de capacitación."}$a3sld$::jsonb,13),
('barreras-para-participar-en-actividades-comunitarias-y-estrategi','sociedad',array[]::text[],'Barreras para participar en actividades comunitarias y estrategias para fomentar la participación','Identifica qué impide a las personas participar, como horarios, información, miedo o costos, y propone estrategias concretas para facilitarlo, pensando en distintos grupos.','Análisis','3 a 4 semanas',24,array['Barreras','Estrategias de participación']::text[],array['investigar','resolver']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de encuestas. analisis cualitativo. pensamiento creativo. comunicacion. un formulario en linea. hoja de calculo. una guia de conversacion.',$a4sld${"id": "barreras-para-participar-en-actividades-comunitarias-y-estrategi", "area": "sociedad", "areas2": [], "titulo": "Barreras para participar en actividades comunitarias y estrategias para fomentar la participación", "resumen": "Identifica qué impide a las personas participar, como horarios, información, miedo o costos, y propone estrategias concretas para facilitarlo, pensando en distintos grupos.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Barreras", "Estrategias de participación"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["A veces se piensa que la gente no participa por apatía, pero muchas barreras son prácticas: reuniones en horarios imposibles, convocatorias que no llegan, lugares inaccesibles o experiencias previas de no ser escuchados.", "Reconocerlas permite diseñar estrategias que sí funcionen."], "desarrollar": ["Con una encuesta breve y voluntaria o conversaciones con vecinos, estudiantes o integrantes de un grupo, reúne las barreras que perciben y clasifícalas en logísticas, de información, de confianza y de inclusión.", "Para las cuatro barreras más mencionadas, propone una estrategia concreta con ejemplos, como cambiar horarios, usar medios distintos o invitar de manera personal, y resume todo en una tabla de barreras y soluciones."], "ampliaciones": [{"titulo": "Prueba piloto", "aporta": "aplica una estrategia en una actividad pequeña y compara asistencia."}, {"titulo": "Por grupos", "aporta": "compara barreras entre jóvenes, adultos y personas mayores."}, {"titulo": "Lista de verificación", "aporta": "crea una lista para revisar si una convocatoria es accesible."}], "objetivos": ["Identificar barreras.", "Clasificarlas.", "Proponer estrategias.", "Resumir en una tabla."], "habilidades": ["Diseño de encuestas.", "Análisis cualitativo.", "Pensamiento creativo.", "Comunicación."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Una guía de conversación."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo análisis sirve para entender por qué los clientes no usan un servicio."}$a4sld$::jsonb,14),
('como-fortalecer-la-organizacion-de-un-grupo-comunitario-o-de-vol','sociedad',array['negocios']::text[],'¿Cómo fortalecer la organización de un grupo comunitario o de voluntarios? Modelo de roles y reparto de responsabilidades','Diseña un modelo de organización para un grupo de voluntarios o vecinos, con roles, reparto de responsabilidades, reuniones, toma de decisiones y formas de evitar que todo recaiga en pocas personas.','Plan','4 semanas',26,array['Organización','Roles']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno organizacional. facilitacion. planificacion. comunicacion. un editor de diagramas. un editor de documentos. companeros para simular una reunion.',$a5sld${"id": "como-fortalecer-la-organizacion-de-un-grupo-comunitario-o-de-vol", "area": "sociedad", "areas2": ["negocios"], "titulo": "¿Cómo fortalecer la organización de un grupo comunitario o de voluntarios? Modelo de roles y reparto de responsabilidades", "resumen": "Diseña un modelo de organización para un grupo de voluntarios o vecinos, con roles, reparto de responsabilidades, reuniones, toma de decisiones y formas de evitar que todo recaiga en pocas personas.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Organización", "Roles"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Muchos grupos comienzan con entusiasmo y se desgastan porque todo depende de una o dos personas, nadie sabe qué le toca o las decisiones se toman sin reglas. Cuando esas personas se van, el grupo se deshace.", "Un modelo sencillo de roles y reglas ayuda a sostener la organización."], "desarrollar": ["Define un grupo de ejemplo con una causa común y diseña su estructura: roles, funciones de cada uno, rotación, forma de tomar decisiones, calendario de reuniones y reglas básicas de convivencia. Dibuja un organigrama simple.", "Anticipa los problemas más probables, como ausencias, conflictos o sobrecarga, y define cómo se resolverían. Pruébalo simulando una reunión con compañeros y ajusta lo que no funcione."], "ampliaciones": [{"titulo": "Relevo de liderazgo", "aporta": "diseña cómo se transmite el liderazgo sin que se rompa el grupo."}, {"titulo": "Registro de acuerdos", "aporta": "crea un formato sencillo de actas."}, {"titulo": "Cuidado de voluntarios", "aporta": "agrega prácticas para evitar el agotamiento."}], "objetivos": ["Definir roles y funciones.", "Diseñar reglas de decisión.", "Anticipar problemas.", "Probar el modelo."], "habilidades": ["Diseño organizacional.", "Facilitación.", "Planificación.", "Comunicación."], "herramientas": ["Un editor de diagramas.", "Un editor de documentos.", "Compañeros para simular una reunión."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Trabaja con un grupo ficticio o con permiso del grupo real."], "otroSector": "El mismo modelo sirve para organizar equipos estudiantiles, clubes o proyectos de trabajo."}$a5sld$::jsonb,15),
('una-red-de-voluntariado-entre-estudiantes-como-conectar-a-quiene','sociedad',array['tecnologia','educacion']::text[],'Una red de voluntariado entre estudiantes: cómo conectar a quienes quieren ayudar con organizaciones comunitarias','Diseña la propuesta de una red que conecte a estudiantes con ganas de ayudar con organizaciones comunitarias que necesitan apoyo, definiendo cómo se registran, se asignan tareas y se da seguimiento.','Plan','4 a 6 semanas',30,array['Red de voluntariado','Organizaciones comunitarias']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno de procesos. gestion de proyectos. redaccion de propuestas. trabajo con organizaciones. un editor de diagramas. un formulario en linea. hoja de calculo.',$a6sld${"id": "una-red-de-voluntariado-entre-estudiantes-como-conectar-a-quiene", "area": "sociedad", "areas2": ["tecnologia", "educacion"], "titulo": "Una red de voluntariado entre estudiantes: cómo conectar a quienes quieren ayudar con organizaciones comunitarias", "resumen": "Diseña la propuesta de una red que conecte a estudiantes con ganas de ayudar con organizaciones comunitarias que necesitan apoyo, definiendo cómo se registran, se asignan tareas y se da seguimiento.", "tipo": "Plan", "tiempo": "4 a 6 semanas", "horas": 30, "etiquetas": ["Red de voluntariado", "Organizaciones comunitarias"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Hay muchos estudiantes dispuestos a ayudar y muchas organizaciones con necesidades concretas, pero casi nunca se encuentran: la oferta y la demanda de ayuda no están conectadas. Esto genera esfuerzos perdidos y voluntarios que se frustran.", "Una red bien diseñada hace que la ayuda llegue donde se necesita."], "desarrollar": ["Define cómo funcionaría la red: qué organizaciones podrían participar, qué tareas piden, cómo se registran los voluntarios, cómo se emparejan necesidades y habilidades, quién coordina y cómo se da seguimiento. Dibuja el flujo completo.", "Redacta una propuesta de dos o tres páginas con reglas de convivencia, responsabilidades de cada parte y riesgos, y prueba el flujo con casos ficticios. No necesitas construir una plataforma: puede operar con formularios y hojas de cálculo."], "ampliaciones": [{"titulo": "Banco de habilidades", "aporta": "arma un catálogo de lo que cada voluntario puede ofrecer."}, {"titulo": "Reconocimiento", "aporta": "diseña formas de reconocer el aporte sin exagerar."}, {"titulo": "Prueba piloto", "aporta": "propón cómo ensayar la red con una sola organización."}], "objetivos": ["Describir el flujo de la red.", "Definir roles y reglas.", "Anticipar riesgos.", "Redactar la propuesta."], "habilidades": ["Diseño de procesos.", "Gestión de proyectos.", "Redacción de propuestas.", "Trabajo con organizaciones."], "herramientas": ["Un editor de diagramas.", "Un formulario en línea.", "Hoja de cálculo."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Presenta la red como propuesta: para operarla se necesita acuerdo de las organizaciones y de la universidad."], "otroSector": "El mismo diseño sirve para conectar profesionales con causas en programas de voluntariado corporativo."}$a6sld$::jsonb,16),
('que-hace-que-una-iniciativa-comunitaria-mantenga-participantes-a','sociedad',array[]::text[],'¿Qué hace que una iniciativa comunitaria mantenga participantes a lo largo del tiempo?','Analiza por qué algunas iniciativas comunitarias logran mantener a sus participantes durante meses o años y otras se apagan rápido, buscando los factores que se repiten.','Investigación','3 a 4 semanas',24,array['Continuidad','Compromiso']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion entrevistas. analisis comparativo. sintesis. redaccion. informes publicos. una guia de entrevista. un editor de documentos.',$a7sld${"id": "que-hace-que-una-iniciativa-comunitaria-mantenga-participantes-a", "area": "sociedad", "areas2": [], "titulo": "¿Qué hace que una iniciativa comunitaria mantenga participantes a lo largo del tiempo?", "resumen": "Analiza por qué algunas iniciativas comunitarias logran mantener a sus participantes durante meses o años y otras se apagan rápido, buscando los factores que se repiten.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Continuidad", "Compromiso"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Es común ver iniciativas que empiezan con mucha gente y a los pocos meses quedan reducidas a un puñado. Otras, en cambio, duran años. La diferencia no suele ser solo el entusiasmo.", "Conocer los factores de continuidad ayuda a diseñar iniciativas que no se apaguen."], "desarrollar": ["Con informes públicos y entrevistas voluntarias a integrantes de dos a tres grupos distintos, identifica qué prácticas se repiten en los que duran: reuniones regulares, reconocimiento, tareas claras, liderazgo compartido y resultados visibles.", "Resume los factores en una lista con ejemplos y arma una guía de diez preguntas para evaluar si una iniciativa tiene condiciones para sostenerse."], "ampliaciones": [{"titulo": "Señales de desgaste", "aporta": "identifica señales tempranas de que un grupo se apaga."}, {"titulo": "Rituales", "aporta": "analiza el papel de celebrar logros."}, {"titulo": "Relevo", "aporta": "estudia cómo se renueva el liderazgo."}], "objetivos": ["Comparar grupos que duran y que se apagan.", "Identificar factores de continuidad.", "Elaborar una lista de verificación.", "Comunicar los hallazgos."], "habilidades": ["Entrevistas.", "Análisis comparativo.", "Síntesis.", "Redacción."], "herramientas": ["Informes públicos.", "Una guía de entrevista.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo análisis sirve para entender la permanencia en equipos de proyectos o en comunidades en línea."}$a7sld$::jsonb,17),
('el-rol-de-las-organizaciones-sociales-en-una-comunidad','sociedad',array['derecho']::text[],'El rol de las organizaciones sociales en una comunidad','Identifica qué organizaciones sociales actúan en una zona, qué hacen y cómo se relacionan con la comunidad, y describe qué aportan y qué dificultades enfrentan.','Investigación','3 semanas',22,array['Organizaciones sociales','Comunidad']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion investigacion de campo. mapeo de actores. entrevistas. redaccion. fuentes publicas. un editor de diagramas. una guia de conversacion.',$a8sld${"id": "el-rol-de-las-organizaciones-sociales-en-una-comunidad", "area": "sociedad", "areas2": ["derecho"], "titulo": "El rol de las organizaciones sociales en una comunidad", "resumen": "Identifica qué organizaciones sociales actúan en una zona, qué hacen y cómo se relacionan con la comunidad, y describe qué aportan y qué dificultades enfrentan.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Organizaciones sociales", "Comunidad"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["En todo barrio hay organizaciones que trabajan por la comunidad, como comedores, clubes de madres, juntas vecinales o asociaciones culturales, pero muchas veces no se las conoce ni se las valora. Tampoco se sabe qué necesitan para seguir funcionando.", "Visibilizar su rol ayuda a apoyarlas y a coordinar mejor."], "desarrollar": ["Elige una zona y, con fuentes públicas y conversaciones con permiso, identifica cinco a ocho organizaciones y describe su propósito, a quiénes atienden, cómo se financian y qué dificultades mencionan. Presenta un perfil breve de cada una.", "Dibuja un mapa de relaciones entre ellas y con las instituciones, resume cómo contribuyen al bienestar de la comunidad e identifica vacíos que no cubre ninguna."], "ampliaciones": [{"titulo": "Línea de tiempo", "aporta": "reconstruye cómo surgió una organización."}, {"titulo": "Necesidades de las organizaciones", "aporta": "pregunta qué apoyo les haría falta."}, {"titulo": "Comparar zonas", "aporta": "compara el tejido social de dos zonas."}], "objetivos": ["Identificar organizaciones.", "Describir su rol.", "Mapear relaciones.", "Reconocer vacíos."], "habilidades": ["Investigación de campo.", "Mapeo de actores.", "Entrevistas.", "Redacción."], "herramientas": ["Fuentes públicas.", "Un editor de diagramas.", "Una guía de conversación."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Pide permiso a cada organización antes de publicar información sobre ella."], "otroSector": "El mismo mapeo sirve para conocer el ecosistema de organizaciones de un sector, como salud o educación."}$a8sld$::jsonb,18),
('participacion-juvenil-en-la-solucion-de-problemas-locales-y-su-p','sociedad',array['educacion']::text[],'Participación juvenil en la solución de problemas locales y su papel en el desarrollo comunitario','Documenta cómo participan los jóvenes en resolver problemas de su zona, qué aportan y qué necesitan para que su participación sea tomada en serio, con ejemplos reales y voluntarios.','Investigación','3 a 4 semanas',24,array['Juventud','Desarrollo comunitario']::text[],array['investigar','crear']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion investigacion de campo. entrevistas. sintesis. redaccion. una guia de conversacion. un editor de documentos. informes publicos.',$a9sld${"id": "participacion-juvenil-en-la-solucion-de-problemas-locales-y-su-p", "area": "sociedad", "areas2": ["educacion"], "titulo": "Participación juvenil en la solución de problemas locales y su papel en el desarrollo comunitario", "resumen": "Documenta cómo participan los jóvenes en resolver problemas de su zona, qué aportan y qué necesitan para que su participación sea tomada en serio, con ejemplos reales y voluntarios.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Juventud", "Desarrollo comunitario"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Se habla de los jóvenes como el futuro, pero muchas veces no se les da lugar en el presente. Sin embargo, hay jóvenes que organizan limpiezas, reforzamientos escolares o campañas y que no siempre son reconocidos.", "Documentar esas experiencias muestra lo que aportan y qué apoyo falta."], "desarrollar": ["Identifica tres a cinco experiencias de participación juvenil en tu zona o en tu institución, con información pública o conversaciones con permiso. Describe qué problema abordaron, qué hicieron, qué lograron y qué obstáculos encontraron.", "Resume lo que tienen en común, qué aportó el hecho de ser jóvenes y qué apoyo habría ayudado. Presenta los hallazgos en un documento breve con testimonios anónimos."], "ampliaciones": [{"titulo": "Línea de tiempo", "aporta": "reconstruye cómo nació y creció una iniciativa."}, {"titulo": "Apoyos útiles", "aporta": "lista los apoyos que más valoran los jóvenes."}, {"titulo": "Comparar con adultos", "aporta": "compara cómo participan jóvenes y adultos."}], "objetivos": ["Documentar experiencias juveniles.", "Identificar aportes y obstáculos.", "Reconocer apoyos necesarios.", "Comunicar los hallazgos."], "habilidades": ["Investigación de campo.", "Entrevistas.", "Síntesis.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de documentos.", "Informes públicos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No expongas a menores: si participan adolescentes, hazlo con autorización de sus familias."], "otroSector": "La misma documentación sirve para recoger experiencias de innovación en equipos de trabajo."}$a9sld$::jsonb,19),
('formas-de-participacion-ciudadana-juvenil-y-que-dificulta-que-lo','sociedad',array['derecho']::text[],'Formas de participación ciudadana juvenil y qué dificulta que los jóvenes participen en las decisiones de su comunidad','Revisa las formas de participación que existen para jóvenes, como consejos, presupuestos participativos o asambleas, y qué factores hacen que muchos no se involucren en las decisiones.','Análisis','3 a 4 semanas',24,array['Participación juvenil','Decisiones']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion lectura de normas. diseno de encuestas. analisis de datos. redaccion. portales oficiales. un formulario en linea. hoja de calculo.',$a10sld${"id": "formas-de-participacion-ciudadana-juvenil-y-que-dificulta-que-lo", "area": "sociedad", "areas2": ["derecho"], "titulo": "Formas de participación ciudadana juvenil y qué dificulta que los jóvenes participen en las decisiones de su comunidad", "resumen": "Revisa las formas de participación que existen para jóvenes, como consejos, presupuestos participativos o asambleas, y qué factores hacen que muchos no se involucren en las decisiones.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Participación juvenil", "Decisiones"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Los jóvenes pueden participar en consejos de juventud, presupuestos participativos, asambleas estudiantiles o iniciativas en redes, pero muchos no lo hacen. Algunos desconocen los espacios, otros sienten que no los escuchan o que son para adultos.", "Entender las formas y las barreras permite diseñar mejores espacios."], "desarrollar": ["Con fuentes oficiales, lista las formas de participación disponibles para jóvenes en tu distrito o institución y describe a quiénes están dirigidas y cómo se accede. Luego, con una encuesta breve y voluntaria, pregunta qué conocen y qué los frena.", "Compara los espacios que existen con lo que los jóvenes dicen conocer y usar, identifica las brechas y propón tres ideas para acercar la participación."], "ampliaciones": [{"titulo": "Participar en redes", "aporta": "analiza el papel de las redes sociales en la participación."}, {"titulo": "Espacio estudiantil", "aporta": "compara participación en la universidad y en el barrio."}, {"titulo": "Guía rápida", "aporta": "crea una guía de una página sobre cómo participar."}], "objetivos": ["Reunir formas de participación.", "Medir conocimiento y uso.", "Identificar brechas.", "Proponer mejoras."], "habilidades": ["Lectura de normas.", "Diseño de encuestas.", "Análisis de datos.", "Redacción."], "herramientas": ["Portales oficiales.", "Un formulario en línea.", "Hoja de cálculo."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Mantén la neutralidad: describe los espacios sin opinar sobre partidos o gestiones.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo análisis sirve para comparar canales de participación de clientes o empleados."}$a10sld$::jsonb,20),
('que-temas-preocupan-mas-a-los-jovenes-de-una-comunidad','sociedad',array[]::text[],'¿Qué temas preocupan más a los jóvenes de una comunidad?','Averigua con una encuesta anónima qué temas preocupan más a los jóvenes de tu zona o institución, como empleo, seguridad, estudios o salud, y compara por grupos.','Investigación','2 a 3 semanas',18,array['Juventud','Preocupaciones']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno de encuestas. estadistica descriptiva. graficos. redaccion. un formulario en linea. hoja de calculo. un editor de graficos.',$a11sld${"id": "que-temas-preocupan-mas-a-los-jovenes-de-una-comunidad", "area": "sociedad", "areas2": [], "titulo": "¿Qué temas preocupan más a los jóvenes de una comunidad?", "resumen": "Averigua con una encuesta anónima qué temas preocupan más a los jóvenes de tu zona o institución, como empleo, seguridad, estudios o salud, y compara por grupos.", "tipo": "Investigación", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Juventud", "Preocupaciones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Se habla de lo que preocupa a los jóvenes sin preguntarles. Las prioridades pueden ser muy distintas a lo que imaginan los adultos y también diferir entre jóvenes de distintos contextos.", "Conocerlas permite que las iniciativas respondan a lo que realmente importa."], "desarrollar": ["Diseña una encuesta anónima de diez preguntas con opciones y una abierta, aplícala a 40 o más jóvenes con consentimiento y analiza qué temas aparecen más, cuáles preocupan más según edad o situación y cuáles creen que nadie atiende.", "Presenta los resultados en gráficos y un resumen de cinco hallazgos, señalando los límites de la muestra, y propone qué iniciativas podrían responder a las tres preocupaciones principales."], "ampliaciones": [{"titulo": "Comparar con adultos", "aporta": "pregunta lo mismo a adultos y compara."}, {"titulo": "Cambio en el tiempo", "aporta": "repite la encuesta meses después."}, {"titulo": "Respuestas posibles", "aporta": "propón acciones para cada preocupación."}], "objetivos": ["Diseñar una encuesta anónima.", "Analizar resultados por grupos.", "Presentar hallazgos con límites.", "Proponer iniciativas."], "habilidades": ["Diseño de encuestas.", "Estadística descriptiva.", "Gráficos.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Si participan menores de edad, pide autorización de sus familias o de la institución."], "otroSector": "La misma encuesta sirve para conocer necesidades de clientes o trabajadores jóvenes."}$a11sld$::jsonb,21),
('disenando-espacios-de-dialogo-para-jovenes','sociedad',array['educacion']::text[],'Diseñando espacios de diálogo para jóvenes','Diseña un espacio de diálogo para jóvenes, como una mesa de conversación o un taller, con reglas, preguntas guía y una forma de registrar lo que se dice y de devolverlo a quienes participaron.','Plan','3 a 4 semanas',22,array['Diálogo','Juventud']::text[],array['crear']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion facilitacion. diseno de dinamicas. comunicacion. planificacion. una hoja de registro. un editor de documentos. un grupo voluntario.',$a12sld${"id": "disenando-espacios-de-dialogo-para-jovenes", "area": "sociedad", "areas2": ["educacion"], "titulo": "Diseñando espacios de diálogo para jóvenes", "resumen": "Diseña un espacio de diálogo para jóvenes, como una mesa de conversación o un taller, con reglas, preguntas guía y una forma de registrar lo que se dice y de devolverlo a quienes participaron.", "tipo": "Plan", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Diálogo", "Juventud"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Los jóvenes suelen tener opiniones valiosas, pero pocas veces hay espacios donde puedan conversar con respeto, sin sentirse evaluados. Un diálogo mal organizado se convierte en discusión o en monólogo.", "Un buen diseño garantiza que todos puedan hablar y que lo conversado sirva para algo."], "desarrollar": ["Define un tema, la duración y el grupo, y diseña la sesión: bienvenida, reglas de convivencia, preguntas guía, dinámicas para que participen todos y un cierre con acuerdos. Prepara los materiales y una hoja de registro anónima.", "Prueba el diseño con cinco a ocho personas, observa qué funcionó y qué no, ajusta las preguntas y el tiempo y redacta una guía breve para facilitadores."], "ampliaciones": [{"titulo": "Versión virtual", "aporta": "adapta el diálogo a una videollamada."}, {"titulo": "Devolución de resultados", "aporta": "diseña cómo compartir lo conversado."}, {"titulo": "Facilitación", "aporta": "prepara consejos para manejar desacuerdos."}], "objetivos": ["Diseñar la sesión.", "Definir reglas y preguntas.", "Probarla con un grupo.", "Redactar una guía."], "habilidades": ["Facilitación.", "Diseño de dinámicas.", "Comunicación.", "Planificación."], "herramientas": ["Una hoja de registro.", "Un editor de documentos.", "Un grupo voluntario."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Establece reglas de respeto y confidencialidad y no registres nombres."], "otroSector": "El mismo diseño sirve para espacios de escucha en equipos de trabajo."}$a12sld$::jsonb,22)
